using System.ComponentModel;
using ModelContextProtocol.Server;

namespace McpServer.Prompts;

[McpServerPromptType]
public sealed class SummarizationPrompt
{
    [McpServerPrompt, Description("Generates a prompt to summarize the provided text.")]
    public static IList<PromptMessage> Summarize(
        [Description("The text content to summarize")] string text,
        [Description("Desired summary style: brief, detailed, or bullet-points")] string style = "brief")
    {
        var systemInstruction = style switch
        {
            "detailed" => "Provide a thorough summary covering all key points.",
            "bullet-points" => "Summarize the text as concise bullet points.",
            _ => "Provide a brief one-paragraph summary."
        };

        return
        [
            new PromptMessage
            {
                Role = Role.User,
                Content = new Content { Type = "text", Text = $"{systemInstruction}\n\nText to summarize:\n{text}" }
            }
        ];
    }
}

